from lesson_helpers import *
from bs4 import BeautifulSoup,NavigableString
pop=[]
def add(k,t,b,ids):pop.append('<template data-pop="c64-'+k+'" data-title="'+html.escape(t,quote=True)+'">'+b+ref(*ids)+'</template>')
terms=[
('biopsie','biopsie','La biopsie doit changer une décision','Une carotte peut identifier malignité et histotype, mais un prélèvement insuffisant ne prouve pas la bénignité. Les performances élevées publiées concernent les prélèvements diagnostiques.','Elle précède une ablation et un traitement systémique sans histologie ; son utilité avant chirurgie ou surveillance dépend de la décision. L’essaimage est rare mais non nul.',['EU-BIOPSY']),
('oncocytome','oncocytome','Oncocytaire ne signifie pas bénin avec certitude','L’imagerie ne distingue pas de manière fiable tous les oncocytomes des carcinomes. Une carotte oncocytaire peut manquer un contingent chromophobe ou d’autres éléments nécessaires à la classification.','Selon OMS 2022, une biopsie à l’aiguille ne permet pas d’affirmer définitivement tous les oncocytomes. Confronter tissu, imagerie et conséquences de la décision.',['EU-HISTO','EU-BIOPSY']),
('surveillance','surveillance active','Surveillance active et attente symptomatique','La surveillance active suit la lésion par imagerie avec possibilité de traitement différé. Elle suppose une organisation, une discussion des critères de changement et l’accord éclairé du patient.','L’attente vigilante vise surtout le contrôle des symptômes lorsque l’on n’anticipe pas d’intervention active ultérieure. Les deux démarches n’ont pas le même objectif.',['EU-LOCAL']),
('vhl','VHL','VHL : voie tumorale et syndrome héréditaire','L’inactivation de VHL dans de nombreux carcinomes à cellules claires favorise l’accumulation de HIF et l’expression de médiateurs proangiogéniques. Il s’agit d’un mécanisme tumoral fréquent.','Une mutation dans la tumeur n’établit pas une variante constitutionnelle transmissible. Le conseil génétique et les tests adaptés répondent à cette autre question.',['EU-MOLEC','EU-GENETIC']),
('hif','HIF','Hypoxie, facteurs de transcription et cible','Les facteurs induits par l’hypoxie participent à une réponse cellulaire au manque d’oxygène. Leur accumulation dans la voie VHL altérée favorise notamment l’expression de VEGF et PDGF.','L’existence d’une cible ne garantit pas une réponse. Belzutifan cible HIF-2α dans certaines situations étudiées ; aucune dose ni autorisation suisse n’est déduite ici de son mécanisme.',['EU-MOLEC']),
('vegf','VEGF','Angiogenèse et toxicités vasculaires','La voie VEGF participe à l’angiogenèse tumorale. Les inhibiteurs de récepteurs à tyrosine kinase ont des profils qui se recouvrent sans être identiques.','Hypertension et protéinurie font partie des risques de plusieurs agents. Surveiller pression et urines ; ne pas remplacer les adaptations propres au produit par un palier commun.',['EU-MOLEC','FI-CABOMETYX','FI-KISPLYX']),
('thrombus','thrombus tumoral','Une extension veineuse de tissu tumoral','La tumeur peut s’étendre dans une veine rénale puis dans la veine cave. La hauteur et l’invasion de paroi influencent la classification et la planification thérapeutique.','Ce tissu n’est pas automatiquement une thrombose sanguine ordinaire. L’imagerie et l’équipe spécialisée distinguent les composantes et décident chirurgie, traitement systémique ou mesures associées.',['EU-TNM','EU-DX','EU-LOCAL']),
('nephrectomie','néphrectomie partielle','Préserver du parenchyme sans perdre l’objectif oncologique','La néphrectomie partielle retire la tumeur avec conservation d’une partie du rein. Elle est privilégiée pour T1 si appropriée ; localisation, complexité et réserve fonctionnelle comptent.','L’avantage de préservation fonctionnelle ne signifie ni risque nul ni preuve certaine d’un gain de survie globale contre la chirurgie radicale dans toutes les populations.',['EU-LOCAL','EU-RISK']),
('bosniak','Bosniak','Classer une lésion kystique, pas toute masse','Bosniak 2019 combine caractères de paroi, septa, nodules et rehaussement. La version et la modalité doivent être identifiées dans le compte rendu.','I et II sont habituellement bénins ; IIF nécessite surveillance ; III et IV conduisent à une discussion proportionnée au risque. Les séries de lésions opérées surestiment parfois la malignité de toutes les lésions découvertes.',['EU-DX','EU-HISTO']),
('sarcomatoide','sarcomatoïde','Une dédifférenciation, pas un histotype autonome','Le contingent sarcomatoïde traduit une dédifférenciation agressive pouvant apparaître dans plusieurs histotypes. Il ne constitue pas simplement une tumeur de grande taille.','Sa présence influence le pronostic et les preuves thérapeutiques, notamment l’intérêt d’associations à base d’immunothérapie dans certaines maladies avancées.',['EU-HISTO','EU-MET']),
('grade','grade','Grade, stade et histotype','Le grade décrit des caractères microscopiques d’agressivité ; le stade décrit l’extension anatomique ; l’histotype décrit la famille tumorale. Une petite tumeur peut avoir un haut grade.','WHO/ISUP s’applique notamment aux cellules claires et papillaires, pas au chromophobe. La biopsie peut sous-échantillonner les zones les plus agressives.',['EU-HISTO','EU-RISK','EU-BIOPSY']),
('pd1','anti-PD1','Lever un frein immunitaire expose aussi les tissus sains','Pembrolizumab et nivolumab ciblent PD-1. Ils peuvent restaurer une activité antitumorale mais provoquer inflammation de divers organes, parfois après l’arrêt.','Le dosage de PD-L1 n’est pas un test de sélection de routine suffisant dans le RCC. Une toxicité se traite selon organe et grade, avec suspension ou arrêt prévu par FI.',['EU-MOLEC','EU-MET','FI-KEYTRUDA']),
('protection','réserve fonctionnelle','Fonction globale et coût d’une intervention','Le rein opposé et le parenchyme restant contribuent au débit global. Une créatinine normale n’exclut pas une tumeur ; une petite masse ne garantit pas une grande réserve.','Documenter fonction antérieure, protéines urinaires et comorbidités ; discuter fonction séparée si elle change la stratégie. Le suivi rénal se poursuit au-delà du calendrier oncologique.',['EU-DX','EU-RISK','EU-FOLLOW']),
('genetique','conseil génétique','Quand envisager une prédisposition ?','Âge ≤46 ans, bilatéralité, multifocalité, histoire familiale ou histologie évocatrice motivent une évaluation selon EAU. Les signes extrarénaux peuvent orienter le syndrome.','VHL, Birt–Hogg–Dubé et FH ont des risques différents. Une stratégie de surveillance fondée sur un seuil de taille dans VHL ne s’étend pas aux tumeurs FH agressives.',['EU-GENETIC']),
('toxicite','toxicité immune','Un symptôme nouveau doit être attribué avec méthode','Colite, pneumopathie, hépatite, néphrite, endocrinopathie ou myocardite peuvent survenir sous inhibiteur de point de contrôle. Plusieurs organes peuvent être atteints simultanément.','Évaluer gravité et causes concurrentes, contacter l’équipe et appliquer les critères spécifiques de suspension/arrêt. Une dose universelle de corticoïde ou une baisse improvisée de l’anticorps n’est pas une conduite suffisante.',['FI-KEYTRUDA','FI-OPDIVO','FI-YERVOY'])]
for k,t,title,p1,p2,ids in terms:add(k,title,'<p>'+p1+'</p><p>'+p2+'</p>',ids)
add('imdc','Calculer IMDC sans changer ses seuils','''<p>Compter un point pour chaque facteur : Karnofsky &lt;80 % ; délai diagnostic–traitement systémique &lt;1 an ; hémoglobine sous la limite inférieure ; calcium corrigé, neutrophiles ou plaquettes au-dessus de leur limite supérieure. Les normes sont celles du laboratoire.</p><p>0 point : favorable ; 1–2 : intermédiaire ; ≥3 : défavorable. Exemple fictif : délai de quatre mois, anémie et neutrophiles élevés = trois points. Les autres facteurs doivent être réellement connus, pas supposés absents.</p><p>Le score concerne la maladie métastatique et le contexte de traitement systémique. Il ne remplace ni le TNM ni les critères d’adjuvant après chirurgie.</p>''',['EU-RISK'])
add('leibovich','Leibovich 2003 : exemple après chirurgie','''<p>Pour un carcinome à cellules claires opéré, le score utilise pT, statut ganglionnaire, taille, grade et nécrose. Les points détaillés figurent dans Examens : 0–2 faible, 3–5 intermédiaire et ≥6 élevé.</p><p>Exemple fictif : pT1b = 2 points ; N0 = 0 ; taille 5 cm = 0 ; grade 2 = 0 ; absence de nécrose = 0. Total 2, groupe faible. Modifier l’histotype ou manquer la donnée de nécrose interdit de prétendre au même calcul complet.</p><p>Le score guide notamment la stratification du suivi. Il ne promet pas l’absence de récidive et ne constitue pas une indication d’immunothérapie à lui seul.</p>''',['EU-RISK','EU-FOLLOW'])
add('adjuvant','Adjuvant : vérifier population, délai et bénéfice','''<p>KEYNOTE-564 étudie certains carcinomes à cellules claires à risque accru après résection : pT2 grade 4/sarcomatoïde N0M0 ; pT3 tout grade N0M0 ; pT4 N0M0 ; tout pT N+M0 ; ou M1 sans maladie résiduelle après résection complète dans l’année suivant la néphrectomie.</p><p>EAU propose restadification et début préférentiellement à 12–16 semaines après néphrectomie. La FI suisse de Keytruda prévoit jusqu’à 12 mois en adjuvant. Le bénéfice doit être mis en balance avec toxicité immune parfois durable et risque de traiter une personne qui n’aurait pas récidivé.</p><p>À 48 mois, les survies globales rapportées sont 91,2 % contre 86,0 % ; le HR de décès est 0,62. La différence absolue à cet horizon est 5,2 points, pas 38 points. Les essais négatifs d’autres agents empêchent d’affirmer un effet de classe.</p>''',['EU-ADJ','FI-KEYTRUDA'])
add('rehaussement','Rehaussement : calcul, unité et limite','''<p>Comparer la densité avant et après contraste dans une région pertinente. Exemple fictif : 63 HU − 28 HU = 35 HU. Le guide EAU retient un gain d’au moins 15 HU comme indice de rehaussement de tissu viable.</p><p>Vérifier phases, région d’intérêt, taille et artefacts. Le gain n’est ni un pourcentage de malignité ni le grade. Oncocytome et certaines autres lésions peuvent aussi rehausser ; l’histologie reste une question distincte.</p>''',['EU-DX'])
add('cas-1','Cas 1 — Une masse incidente de 3,2 cm','''<p>Une personne de 67 ans, sans symptômes, a une masse de 3,2 cm. Doit-on proposer d’emblée une néphrectomie totale ?</p><p><b>Réponse : non.</b> Caractériser solide/kystique, rehaussement, extension, rein opposé et fonction. Discuter histologie si utile à la décision. Une chirurgie partielle peut être appropriée pour T1 ; surveillance active ou autre traitement local se discutent selon risque et contexte.</p><p>La taille n’impose ni chirurgie totale ni absence de traitement. La décision précise objectif, bénéfices, risques et organisation du suivi.</p>''',['CH-MASSES','EU-DX','EU-LOCAL'])
add('cas-2','Cas 2 — Trois facteurs IMDC','''<p>Une maladie métastatique doit être traitée quatre mois après diagnostic. L’hémoglobine est sous la norme et les neutrophiles au-dessus ; calcium corrigé et plaquettes sont normaux, Karnofsky 90 %. Quel groupe ?</p><p><b>Réponse : trois facteurs, risque défavorable.</b> Le délai, l’anémie et les neutrophiles comptent chacun un point. Karnofsky 90 % n’ajoute pas de point. La norme est celle du laboratoire.</p><p>Le résultat oriente le pronostic et la stratégie systémique ; il ne justifie pas une néphrectomie cytoréductrice immédiate systématique ni l’abandon des soins.</p>''',['EU-RISK','EU-MET'])
add('cas-3','Cas 3 — Diarrhée après nivolumab–ipilimumab','''<p>Après induction, une personne signale une diarrhée persistante et des douleurs abdominales. Faut-il attendre la prochaine perfusion pour en parler ?</p><p><b>Réponse : non.</b> Contacter rapidement l’équipe, évaluer fréquence, retentissement, déshydratation, fièvre et signes de gravité ; rechercher colite immune et causes concurrentes, notamment infection. La prise en charge et la suspension/arrêt suivent organe et grade.</p><p>Ne pas attribuer une diarrhée importante à un simple inconfort attendu ni donner un schéma de corticoïde indifférencié. Les toxicités peuvent apparaître après l’arrêt de l’anticorps.</p>''',['FI-OPDIVO','FI-YERVOY','FI-KEYTRUDA'])
add('cas-4','Cas 4 — Une petite tumeur peut dépasser T1','''<p>Une masse de 3,8 cm rehausse de 28 à 63 HU et s’étend dans une branche segmentaire de la veine rénale. Peut-on la classer T1a parce qu’elle mesure moins de 4 cm ?</p><p><b>Réponse : non.</b> Le gain de 35 HU soutient le rehaussement, pas le grade. L’extension veineuse décrite correspond à T3a dans la classification TNM 2017 utilisée par EAU 2026, si elle est confirmée selon le niveau de preuve clinique/pathologique.</p><p>La taille seule n’épuise pas T. Il reste à établir N, M, histotype, fonction et stratégie ; aucun score métastatique n’est calculé sans données adaptées.</p>''',['EU-DX','EU-TNM','EU-RISK'])
# Edit the complete canonical template once. Never serialize its unfinished fragments separately.
parts=['a','b','c','d'];joined=''.join((CH/f'C64_{x}.html').read_text()+f'<!--C64-CUT-{x}-->' for x in parts);s=BeautifulSoup(joined,'html.parser')
for k,term,*_ in terms:
 for panel in s.select('.panel'):
  for node in list(panel.find_all(string=True)):
   if not isinstance(node,NavigableString) or not node.parent or any(t.name in ['button','a','style','script','h1','h2','h3','figcaption'] or 'src' in t.get('class',[]) for t in node.parents):continue
   if term in str(node):
    before,after=str(node).split(term,1);node.replace_with(NavigableString(before),BeautifulSoup(w(k,term),'html.parser'),NavigableString(after));break
pareto=[
('Une masse est un constat ; C64 désigne un siège et non un histotype.','EU-DX'),('Les chiffres suisses 2018–2022 sont des moyennes annuelles, pas un risque individuel.','CH-EPI'),('VHL–HIF–VEGF relie biologie et angiogenèse, sans prédire seul la réponse.','EU-MOLEC'),('Sécuriser, caractériser, établir utilité de la biopsie puis décider avec le patient.','EU-DX'),('La chronologie et les traitements orientent maladie, complication et toxicité.','EU-DX'),('L’examen normal n’exclut pas une petite masse ; rechercher le retentissement.','EU-DX'),('Histotype, grade, stade, IMDC et Leibovich ont des finalités distinctes.','EU-RISK'),('L’imagerie est suspecte ; le tissu précise, avec limites d’échantillonnage.','EU-BIOPSY'),('Chaque examen répond à une question de lésion, extension ou fonction.','EU-DX'),('Parenchyme, cavités, kyste et masse solide ne suivent pas le même parcours.','EU-HISTO'),('Confronter contrôle tumoral, fonction, risques et cadre suisse des médicaments.','EU-LOCAL'),('Le suivi inclut récidive, fonction rénale, pression et qualité de vie.','EU-FOLLOW'),('Les exercices sont pédagogiques, avec éditions des objectifs explicites.','CH-PROFILES'),('Éviter les extrapolations de population, de dose et de preuve.','EU-MET')]
for i,(summary,sid) in enumerate(pareto,1):
 section=s.find(id=f'c64-{i}'); section.append(BeautifulSoup('<p class="ui">'+w(f'pareto-{i}','Synthèse 20/80 — '+str(i))+'</p>','html.parser'));add(f'pareto-{i}','Synthèse 20/80 — '+str(i),'<p>'+summary+'</p><p>Relire la section complète pour les critères, les limites et les décisions ; cette synthèse ne remplace pas le contexte.</p>',[sid])
quizzes=[('Une biopsie non diagnostique prouve-t-elle la bénignité ?','Non, réévaluer la concordance et la conduite.','Oui, le cancer est exclu.','Un prélèvement insuffisant ne constitue pas un test négatif valide.','EU-BIOPSY'),('Quel schéma initial nivo/ipi correspond au rein dans les FI suisses ?','Nivolumab 3 mg/kg + ipilimumab 1 mg/kg.','Nivolumab 1 mg/kg + ipilimumab 3 mg/kg.','Ne pas copier les doses du mélanome.','FI-YERVOY'),('Une recommandation EAU au risque favorable élargit-elle l’autorisation suisse ?','Non, vérifier les FI exactes et le cadre de prise en charge.','Oui, automatiquement.','Les quatre associations lues ont une indication suisse intermédiaire/défavorable.','FI-KEYTRUDA'),('Une masse de 3,8 cm avec extension veineuse segmentaire est-elle T1a ?','Non, l’extension décrite correspond à T3a.','Oui, seule la taille compte.','TNM décrit aussi l’extension, dans l’édition2017 citée.','EU-TNM')]
for q,yes,no,ex,sid in quizzes:s.find(id='c64-13').append(BeautifulSoup('<div class="quiz ui"><p>'+q+'</p><button data-ok="1">'+yes+'</button><button data-ok="0">'+no+'</button><p class="fb" hidden>'+ex+'</p></div>'+ref(sid),'html.parser'))
text=str(s)
for x in parts:
 body,text=text.split(f'<!--C64-CUT-{x}-->',1);save(x,body)
save('pop1','\n'.join(pop[:19]));save('pop2','\n'.join(pop[19:]));print(len(pop),'fenêtres dont14synthèses ;4quiz ; template entier préservé')
